import os,sys,re
root,svc,env,host=sys.argv[1:5]
cfg={}
def read(p,name):
    sec=None
    for l in open(p):
        l=l.strip()
        if not l or l.startswith('#'):continue
        if l.startswith('['):
            sec=l[1:-1];continue
        k,_,v=l.partition('=');k=k.strip();v=v.strip()
        if k=='include':
            if sec is None:
                q=os.path.normpath(os.path.join(os.path.dirname(p),v.replace('${env}',env).replace('${host}',host)))
                read(q,name)
            continue
        if sec is None or sec==name: cfg[k]=v; 
read(f'/app/services/{svc}/service.conf',svc) if False else None
E
cd /app; sed -n 1,5p services/tagging/service.conf >/dev/null; ls services | wc -l; grep -L "^include" services/*/service.conf | head; grep -h "^include" services/*/service.conf | sort | uniq -c

